import 'package:flutter_test/flutter_test.dart';
import 'package:medcases/services/clinical_thread_manager.dart';
void main(){test('continuity metadata',(){
final cases=[['Explique encefalopatía hepática.','E qual seria o tratamento de primeira linha?'],['Explique metformina.','E quais são as principais contraindicações dela?'],['Explica metformina.','¿Y cuáles son las principales contraindicaciones de ella?'],['Paciente com hiperkalemia.','E se o ECG mostrar alterações?'],['Explique sódio sérico.','E nesse contexto?'],['Explique a diretriz de asma.','Qual alternativa?']];
for(var i=0;i<cases.length;i++){final m=ClinicalThreadManager();m.evaluate(currentUserText:cases[i][0],isPlantaoMode:true);final r=m.evaluate(currentUserText:cases[i][1],isPlantaoMode:true);expect(r.isContinuation,isTrue,reason:'case $i'); final history=ClinicalThreadManager.buildThreadHistory(fullHistory:[{'role':'user','content':cases[i][0]},{'role':'assistant','content':'Synthetic previous answer'}],status:r,isPlantaoMode:true); expect(history.length,2); final longHistory=[...history,for(var n=0;n<10;n++) ...[{'role':'user','content':'follow-up $n'},{'role':'assistant','content':'answer $n'}]]; final compact=ClinicalThreadManager.buildThreadHistory(fullHistory:longHistory,status:r,isPlantaoMode:true);expect(compact.first['content'],cases[i][0]);expect(compact.last['content'],'answer 9'); final id=m.activeThreadId; expect(m.evaluate(currentUserText:'E nesse contexto?',isPlantaoMode:true).isContinuation,isTrue); expect(m.activeThreadId,id); expect(m.evaluate(currentUserText:'Agora mude de tema: fale sobre asma.',isPlantaoMode:true).isContinuation,isFalse);}
});}
